import"./chunk-VC46IEJQ.js";var e={group:"crownlands",places:[{id:"kings-landing",summary:{en:"Aegon the Conqueror landed here with his sisters and raised a timber fort on the highest of three hills; within a century it had become the largest city of the Seven Kingdoms. The Red Keep, the Great Sept of Baelor and the Dragonpit crown its hills, while the poor crowd into Flea Bottom below. It is crowded, rich and notorious for its smell.",zh:"\u5F81\u670D\u8005\u4F0A\u803F\u4E0E\u4E24\u4F4D\u59D0\u59B9\u5728\u6B64\u767B\u9646\uFF0C\u5728\u4E09\u5EA7\u5C71\u4E18\u4E2D\u6700\u9AD8\u7684\u4E00\u5EA7\u4E0A\u7B51\u8D77\u6728\u5821\uFF1B\u4E0D\u5230\u767E\u5E74\uFF0C\u8FD9\u91CC\u4FBF\u6210\u4E86\u4E03\u5927\u738B\u56FD\u6700\u5927\u7684\u57CE\u5E02\u3002\u7EA2\u5821\u3001\u8D1D\u52D2\u5927\u5723\u5802\u4E0E\u9F99\u7A74\u5404\u636E\u5C71\u5934\uFF0C\u7A77\u4EBA\u5219\u6324\u5728\u5C71\u4E0B\u7684\u8DF3\u86A4\u7A9D\u91CC\u3002\u57CE\u4E2D\u4EBA\u70DF\u7A20\u5BC6\u3001\u8D22\u5BCC\u6C47\u805A\uFF0C\u6C14\u5473\u4E4B\u96BE\u95FB\u4E5F\u540C\u6837\u51FA\u540D\u3002"},houses:["targaryen","blount","chelsted"],refs:["agot","acok","twoiaf"],confidence:"high",spoiler:{en:"In A Feast for Crows the Great Sept becomes the seat of a newly armed Faith; by the end of A Dance with Dragons the city is ruled by a regency council after Kevan Lannister's murder.",zh:"\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u4E2D\uFF0C\u91CD\u65B0\u6B66\u88C5\u8D77\u6765\u7684\u6559\u4F1A\u4EE5\u8D1D\u52D2\u5927\u5723\u5802\u4E3A\u636E\u70B9\uFF1B\u81F3\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u7ED3\u5C3E\uFF0C\u51EF\u51AF\xB7\u5170\u5C3C\u65AF\u7279\u9047\u523A\uFF0C\u57CE\u4E2D\u7531\u6444\u653F\u4F1A\u8BAE\u638C\u6743\u3002"}},{id:"dragonstone",summary:{en:"An island fortress beneath the smoking Dragonmont, raised by Valyrian masons whose stone seems shaped rather than cut, its walls crowded with dragons and gargoyles. The Targaryens held it for a century before the Conquest, and it became the traditional seat of the heir to the throne. In the books it is held by Stannis Baratheon and serves as his base in the war.",zh:"\u70DF\u96FE\u7F2D\u7ED5\u7684\u9F99\u5C71\u811A\u4E0B\u7684\u5C9B\u4E0A\u8981\u585E\uFF0C\u7531\u74E6\u96F7\u5229\u4E9A\u77F3\u5320\u5EFA\u9020\uFF0C\u77F3\u6750\u4EFF\u4F5B\u662F\u88AB\u5851\u51FA\u6765\u800C\u975E\u51FF\u51FA\u6765\u7684\uFF0C\u57CE\u5899\u4E0A\u6EE1\u662F\u5DE8\u9F99\u4E0E\u77F3\u50CF\u9B3C\u96D5\u9970\u3002\u5F81\u670D\u4E4B\u524D\uFF0C\u5766\u683C\u5229\u5B89\u5BB6\u65CF\u5DF2\u5728\u6B64\u76D8\u8E1E\u767E\u5E74\uFF0C\u6B64\u540E\u8FD9\u91CC\u4F20\u7EDF\u4E0A\u5F52\u738B\u4F4D\u7EE7\u627F\u4EBA\u6240\u6709\u3002\u5C0F\u8BF4\u4E2D\u5B83\u7531\u53F2\u5766\u5C3C\u65AF\xB7\u62DC\u62C9\u5E2D\u6069\u636E\u5B88\uFF0C\u662F\u4ED6\u5728\u6218\u4E89\u4E2D\u7684\u6839\u636E\u5730\u3002"},houses:["targaryen"],refs:["acok","asos","twoiaf"],confidence:"high"},{id:"blackwater-bay",kind:"bay",region:"crownlands",at:[528,934],rank:3,names:{en:"Blackwater Bay",zh:"\u9ED1\u6C34\u6E7E"},alt:["Blackwater"],summary:{en:"The broad bay between Crackclaw Point and Massey's Hook, fed by the Blackwater Rush. King's Landing sits at its head, Duskendale on its northern shore, and Dragonstone and Driftmark guard its mouth. Whoever commands its waters controls the sea road to the capital.",zh:"\u5939\u5728\u87F9\u722A\u534A\u5C9B\u4E0E\u6885\u897F\u94A9\u4E4B\u95F4\u7684\u5BBD\u9614\u6D77\u6E7E\uFF0C\u9ED1\u6C34\u6CB3\u6CE8\u5165\u5176\u4E2D\u3002\u541B\u4E34\u4F4D\u4E8E\u6E7E\u5E95\uFF0C\u66AE\u8C37\u9547\u5728\u5317\u5CB8\uFF0C\u9F99\u77F3\u5C9B\u4E0E\u6F6E\u5934\u5C9B\u628A\u5B88\u6E7E\u53E3\u3002\u8C01\u638C\u63A7\u8FD9\u7247\u6C34\u57DF\uFF0C\u8C01\u5C31\u627C\u4F4F\u4E86\u901A\u5F80\u9996\u90FD\u7684\u6D77\u8DEF\u3002"},houses:[],refs:["agot","acok","maps"],confidence:"high"},{id:"blackwater-rush",kind:"river",region:"crownlands",at:[392,920],rank:3,names:{en:"The Blackwater Rush",zh:"\u9ED1\u6C34\u6CB3"},alt:["Blackwater","Blackwater River"],summary:{en:"A deep, swift river running east from the hills of the westerlands, south of the Gods Eye, to empty into Blackwater Bay beneath King's Landing. It roughly marks the southern edge of the riverlands and is hard to ford near the capital. Its mouth was the scene of Stannis Baratheon's defeat in A Clash of Kings.",zh:"\u4E00\u6761\u6C34\u6DF1\u6D41\u6025\u7684\u6CB3\u6D41\uFF0C\u81EA\u897F\u5883\u4E18\u9675\u5411\u4E1C\u5954\u6D41\uFF0C\u7ECF\u795E\u773C\u6E56\u4EE5\u5357\uFF0C\u5728\u541B\u4E34\u57CE\u4E0B\u6CE8\u5165\u9ED1\u6C34\u6E7E\u3002\u5B83\u5927\u81F4\u6784\u6210\u6CB3\u95F4\u5730\u7684\u5357\u754C\uFF0C\u9760\u8FD1\u9996\u90FD\u4E00\u5E26\u96BE\u4EE5\u6D89\u6E21\u3002\u300A\u5217\u738B\u7684\u7EB7\u4E89\u300B\u4E2D\uFF0C\u53F2\u5766\u5C3C\u65AF\xB7\u62DC\u62C9\u5E2D\u6069\u6B63\u662F\u5728\u5176\u6CB3\u53E3\u5175\u8D25\u3002"},houses:[],refs:["agot","acok","maps"],confidence:"high"},{id:"the-gullet",kind:"bay",region:"crownlands",at:[580,957],rank:2,names:{en:"The Gullet",zh:"\u54BD\u5589\u6D77\u5CE1"},alt:["Gullet","\u54BD\u5589"],summary:{en:"The narrow sea passage between Driftmark and Massey's Hook, one of the gates between Blackwater Bay and the Narrow Sea. Ships bound for King's Landing from the south pass through it, which made it a natural battleground.",zh:"\u6F6E\u5934\u5C9B\u4E0E\u6885\u897F\u94A9\u4E4B\u95F4\u7684\u72ED\u7A84\u6C34\u9053\uFF0C\u662F\u9ED1\u6C34\u6E7E\u901A\u5F80\u72ED\u6D77\u7684\u95E8\u6237\u4E4B\u4E00\u3002\u4ECE\u5357\u65B9\u9A76\u5F80\u541B\u4E34\u7684\u8239\u53EA\u5FC5\u7ECF\u6B64\u5730\uFF0C\u56E0\u800C\u5929\u7136\u4FBF\u662F\u5175\u5BB6\u5FC5\u4E89\u4E4B\u5904\u3002"},houses:["velaryon"],refs:["twoiaf","maps"],confidence:"medium"},{id:"crackclaw-point",kind:"forest",region:"crownlands",at:[560,886],rank:3,names:{en:"Crackclaw Point",zh:"\u87F9\u722A\u534A\u5C9B"},alt:["Crackclaw"],summary:{en:"A rugged peninsula of pine forest, bogs, hills and rocky shore between the Bay of Crabs and Blackwater Bay. Its petty lords and clannish folk distrust outsiders, feud among themselves, and kept faith with the Targaryens long after the dragons fell. Only the dragonlords ever truly brought it to heel.",zh:"\u4F4D\u4E8E\u8783\u87F9\u6E7E\u4E0E\u9ED1\u6C34\u6E7E\u4E4B\u95F4\u7684\u5D0E\u5C96\u534A\u5C9B\uFF0C\u677E\u6797\u3001\u6CBC\u6CFD\u3001\u4E18\u9675\u4E0E\u7901\u5CB8\u4EA4\u9519\u3002\u8FD9\u91CC\u7684\u5C0F\u9886\u4E3B\u548C\u5B97\u65CF\u4E61\u6C11\u6392\u65A5\u5916\u4EBA\u3001\u5F7C\u6B64\u4E16\u4EC7\u4E0D\u65AD\uFF0C\u9F99\u738B\u671D\u8986\u706D\u540E\u4ECD\u957F\u671F\u5FC3\u5411\u5766\u683C\u5229\u5B89\u5BB6\u65CF\u3002\u771F\u6B63\u8BA9\u5B83\u4FEF\u9996\u7684\uFF0C\u552F\u6709\u5F53\u5E74\u7684\u9F99\u738B\u3002"},houses:["brune-of-brownhollow","brune-of-the-dyre-den","boggs","crabb"],refs:["acok","affc","twoiaf"],confidence:"high"},{id:"masseys-hook",kind:"island",region:"crownlands",at:[566,976],rank:2,names:{en:"Massey's Hook",zh:"\u6885\u897F\u94A9"},alt:["Masseys Hook"],summary:{en:"The peninsula that closes Blackwater Bay to the south-east, reaching out toward Driftmark. Its castles \u2014 Sharp Point, Stonedance and Sweetport Sound \u2014 owe service to Dragonstone rather than to King's Landing. (A peninsula, filed here among islands for labelling.)",zh:"\u4ECE\u4E1C\u5357\u65B9\u5408\u62E2\u9ED1\u6C34\u6E7E\u7684\u534A\u5C9B\uFF0C\u5411\u6F6E\u5934\u5C9B\u65B9\u5411\u4F38\u51FA\u3002\u534A\u5C9B\u4E0A\u7684\u9510\u89D2\u57CE\u3001\u77F3\u821E\u57CE\u548C\u751C\u6E2F\u6E7E\u7B49\u57CE\u5821\u6548\u5FE0\u9F99\u77F3\u5C9B\uFF0C\u800C\u975E\u541B\u4E34\u3002\uFF08\u5B9E\u4E3A\u534A\u5C9B\uFF0C\u4E3A\u6807\u6CE8\u65B9\u4FBF\u5F52\u5165\u5C9B\u5C7F\u7C7B\u3002\uFF09"},houses:["massey","bar-emmon","sunglass"],refs:["acok","twoiaf","maps"],confidence:"medium"},{id:"driftmark",kind:"island",region:"crownlands",at:[570,944],rank:3,names:{en:"Driftmark",zh:"\u6F6E\u5934\u5C9B"},alt:["Drift Mark"],summary:{en:"The largest island in Blackwater Bay, lying west of Dragonstone. It is the ancient domain of House Velaryon, whose fleets and sea trade once made them the richest house in the realm. Its towns and shipyards face the Gullet and the bay.",zh:"\u9ED1\u6C34\u6E7E\u4E2D\u6700\u5927\u7684\u5C9B\u5C7F\uFF0C\u4F4D\u4E8E\u9F99\u77F3\u5C9B\u4EE5\u897F\u3002\u8FD9\u91CC\u662F\u74E6\u5217\u5229\u5B89\u5BB6\u65CF\u7684\u53E4\u8001\u9886\u5730\uFF0C\u5176\u8230\u961F\u4E0E\u6D77\u4E0A\u8D38\u6613\u4E00\u5EA6\u4EE4\u8BE5\u5BB6\u65CF\u5BCC\u7532\u738B\u56FD\u3002\u5C9B\u4E0A\u57CE\u9547\u4E0E\u8239\u575E\u9762\u671D\u54BD\u5589\u6D77\u5CE1\u548C\u6D77\u6E7E\u3002"},houses:["velaryon"],refs:["acok","twoiaf"],confidence:"high"},{id:"claw-isle",kind:"island",region:"crownlands",at:[602,878],rank:2,names:{en:"Claw Isle",zh:"\u722A\u5C9B"},alt:["Claw Island"],summary:{en:"A small island off the tip of Crackclaw Point, seat of House Celtigar, one of the Valyrian-descended houses that came west with the Targaryens. The Celtigars are said to keep a hoard of Myrish carpets, Volantene glass and gold plate in their castle.",zh:"\u87F9\u722A\u534A\u5C9B\u5C16\u7AEF\u5916\u7684\u5C0F\u5C9B\uFF0C\u8D5B\u63D0\u52A0\u5BB6\u65CF\u7684\u5C45\u57CE\u6240\u5728\uFF1B\u8BE5\u5BB6\u65CF\u4E0E\u5766\u683C\u5229\u5B89\u5BB6\u65CF\u4E00\u540C\u897F\u6765\uFF0C\u6709\u74E6\u96F7\u5229\u4E9A\u8840\u7EDF\u3002\u636E\u8BF4\u5176\u57CE\u5821\u91CC\u85CF\u7740\u5BC6\u5C14\u5730\u6BEF\u3001\u74E6\u5170\u63D0\u65AF\u73BB\u7483\u5668\u548C\u91D1\u5668\u3002"},houses:["celtigar"],refs:["acok","twoiaf"],confidence:"high"},{id:"dragonmont",kind:"mountain",region:"crownlands",at:[600,921],rank:2,names:{en:"Dragonmont",zh:"\u9F99\u5C71"},alt:["Dragon Mont"],summary:{en:"The smoking volcano that rises behind the castle of Dragonstone. Its warm caves once housed the Targaryens' dragons, and the island beneath it is rich in dragonglass. Sailors say it still rumbles and steams.",zh:"\u9F99\u77F3\u5C9B\u57CE\u5821\u80CC\u540E\u5192\u7740\u70DF\u7684\u706B\u5C71\u3002\u5C71\u4E2D\u6E29\u6696\u7684\u6D1E\u7A74\u66FE\u662F\u5766\u683C\u5229\u5B89\u5BB6\u65CF\u5DE8\u9F99\u7684\u5DE2\u7A74\uFF0C\u5C71\u4E0B\u5C9B\u4E0A\u9F99\u6676\uFF08\u5373\u9ED1\u66DC\u77F3\uFF09\u50A8\u91CF\u4E30\u5BCC\u3002\u6C34\u624B\u4EEC\u8BF4\u5B83\u81F3\u4ECA\u4ECD\u4F1A\u8F70\u9E23\u3001\u55B7\u5410\u84B8\u6C7D\u3002"},houses:["targaryen"],refs:["acok","adwd","twoiaf"],confidence:"high"},{id:"high-tide",kind:"castle",region:"crownlands",at:[580,948],rank:2,names:{en:"High Tide",zh:"\u6EE1\u6F6E\u5821"},alt:["\u9AD8\u6F6E\u57CE","\u6F6E\u6C50\u5821"],summary:{en:"The later seat of House Velaryon, built by the seafaring lord Corlys Velaryon on a tidal islet off Driftmark, reachable on foot only at low tide. Its halls were furnished with the wealth of his voyages. In the books it remains the Velaryon seat.",zh:"\u74E6\u5217\u5229\u5B89\u5BB6\u65CF\u540E\u671F\u7684\u5C45\u57CE\uFF0C\u7531\u822A\u6D77\u5BB6\u79D1\u5229\u65AF\xB7\u74E6\u5217\u5229\u5B89\u4F2F\u7235\u5EFA\u4E8E\u6F6E\u5934\u5C9B\u5916\u7684\u4E00\u5EA7\u6F6E\u6C50\u5C0F\u5C9B\u4E0A\uFF0C\u53EA\u6709\u9000\u6F6E\u65F6\u624D\u80FD\u6B65\u884C\u62B5\u8FBE\u3002\u57CE\u4E2D\u9648\u8BBE\u5C3D\u662F\u4ED6\u8FDC\u822A\u6240\u5F97\u7684\u8D22\u5BCC\u3002\u5C0F\u8BF4\u4E2D\u8FD9\u91CC\u4ECD\u662F\u74E6\u5217\u5229\u5B89\u5BB6\u65CF\u7684\u5C45\u57CE\u3002"},houses:["velaryon"],refs:["affc","twoiaf"],confidence:"medium"},{id:"castle-driftmark",kind:"castle",region:"crownlands",at:[560,941],rank:1,names:{en:"Castle Driftmark",zh:"\u6F6E\u5934\u5821"},alt:["Driftmark Castle"],summary:{en:"The older seat of House Velaryon on the north side of the island, above the town of Hull. It was overshadowed once High Tide was built, but the Velaryons kept it as a second stronghold.",zh:"\u74E6\u5217\u5229\u5B89\u5BB6\u65CF\u8F83\u65E9\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u5C9B\u7684\u5317\u4FA7\uFF0C\u4FEF\u4E34\u8D6B\u5C14\u9547\u3002\u6EE1\u6F6E\u5821\u5EFA\u6210\u540E\u5B83\u4FBF\u9000\u5C45\u6B21\u5E2D\uFF0C\u4F46\u74E6\u5217\u5229\u5B89\u5BB6\u65CF\u4ECD\u5C06\u5176\u4F5C\u4E3A\u7B2C\u4E8C\u5EA7\u8981\u585E\u3002"},houses:["velaryon"],refs:["twoiaf"],confidence:"medium"},{id:"hull",kind:"town",region:"crownlands",at:[566,939],rank:1,names:{en:"Hull",zh:"\u8D6B\u5C14\u9547"},alt:["\u8239\u58F3\u9547"],summary:{en:"A shipbuilding town beneath the walls of Castle Driftmark on the north side of the island. Its yards built many of the Velaryon ships that once made up the strength of the royal fleet.",zh:"\u6F6E\u5934\u5C9B\u5317\u4FA7\u3001\u6F6E\u5934\u5821\u57CE\u5899\u4E0B\u7684\u9020\u8239\u5C0F\u9547\u3002\u5F53\u5E74\u6784\u6210\u738B\u5BB6\u8230\u961F\u4E3B\u529B\u7684\u74E6\u5217\u5229\u5B89\u6218\u8239\uFF0C\u4E0D\u5C11\u51FA\u81EA\u8FD9\u91CC\u7684\u8239\u575E\u3002"},houses:["velaryon"],refs:["twoiaf"],confidence:"medium"},{id:"spicetown",kind:"ruin",region:"crownlands",at:[565,948],rank:1,names:{en:"Spicetown",zh:"\u9999\u6599\u9547"},alt:["Spice Town"],summary:{en:"Once a busy port on Driftmark's south shore near High Tide, grown rich on the Velaryon trade with the east. It was sacked and burned by a fleet from the Free Cities during the Dance of the Dragons and never rebuilt.",zh:"\u66FE\u662F\u6F6E\u5934\u5C9B\u5357\u5CB8\u3001\u6EE1\u6F6E\u5821\u9644\u8FD1\u7684\u7E41\u5FD9\u6E2F\u53E3\uFF0C\u9760\u74E6\u5217\u5229\u5B89\u5BB6\u65CF\u4E0E\u4E1C\u65B9\u7684\u8D38\u6613\u800C\u81F4\u5BCC\u3002\u201C\u8840\u9F99\u72C2\u821E\u201D\u671F\u95F4\u906D\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u7684\u8230\u961F\u6D17\u52AB\u711A\u6BC1\uFF0C\u6B64\u540E\u518D\u672A\u91CD\u5EFA\u3002"},houses:["velaryon"],refs:["twoiaf"],confidence:"medium"},{id:"sharp-point",kind:"castle",region:"crownlands",at:[583,976],rank:2,names:{en:"Sharp Point",zh:"\u9510\u89D2\u57CE"},alt:["\u5C16\u89D2\u57CE"],summary:{en:"Seat of House Bar Emmon at the northern end of Massey's Hook, looking out over the Gullet toward Driftmark. Its young lord, Duram Bar Emmon, is among the Dragonstone bannermen who follow Stannis.",zh:"\u5DF4\u5C14\xB7\u827E\u8499\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u6885\u897F\u94A9\u5317\u7AEF\uFF0C\u9694\u54BD\u5589\u6D77\u5CE1\u9065\u671B\u6F6E\u5934\u5C9B\u3002\u5E74\u8F7B\u7684\u57CE\u4E3B\u675C\u62C9\u59C6\xB7\u5DF4\u5C14\xB7\u827E\u8499\u662F\u8FFD\u968F\u53F2\u5766\u5C3C\u65AF\u7684\u9F99\u77F3\u5C9B\u5C01\u81E3\u4E4B\u4E00\u3002"},houses:["bar-emmon"],refs:["acok","twoiaf"],confidence:"medium"},{id:"stonedance",kind:"castle",region:"crownlands",at:[570,985],rank:2,names:{en:"Stonedance",zh:"\u77F3\u821E\u57CE"},alt:["Stone Dance"],summary:{en:"Seat of the ancient House Massey on Massey's Hook, to which the peninsula owes its name. The Masseys are sworn to Dragonstone and sided with Stannis in the war.",zh:"\u53E4\u8001\u7684\u6885\u897F\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5750\u843D\u4E8E\u4EE5\u8BE5\u5BB6\u65CF\u547D\u540D\u7684\u6885\u897F\u94A9\u4E0A\u3002\u6885\u897F\u5BB6\u65CF\u6548\u5FE0\u9F99\u77F3\u5C9B\uFF0C\u5728\u6218\u4E89\u4E2D\u7AD9\u5728\u53F2\u5766\u5C3C\u65AF\u4E00\u8FB9\u3002"},houses:["massey"],refs:["acok","twoiaf"],confidence:"medium"},{id:"sweetport-sound",kind:"castle",region:"crownlands",at:[549,993],rank:1,names:{en:"Sweetport Sound",zh:"\u751C\u6E2F\u6E7E"},alt:["Sweetport"],summary:{en:"Seat of House Sunglass on Massey's Hook, sworn to Dragonstone. Its lord Guncer Sunglass was a devout follower of the Seven who balked at Stannis's new red faith.",zh:"\u6851\u683C\u62C9\u65AF\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u6885\u897F\u94A9\uFF0C\u6548\u5FE0\u9F99\u77F3\u5C9B\u3002\u57CE\u4E3B\u5188\u745F\xB7\u6851\u683C\u62C9\u65AF\u662F\u8654\u8BDA\u7684\u4E03\u795E\u4FE1\u5F92\uFF0C\u5BF9\u53F2\u5766\u5C3C\u65AF\u6539\u5949\u7684\u7EA2\u795E\u4FE1\u4EF0\u5FC3\u5B58\u62B5\u89E6\u3002"},houses:["sunglass"],refs:["asos","twoiaf"],confidence:"low"},{id:"stokeworth",kind:"castle",region:"crownlands",at:[490,915],rank:2,names:{en:"Stokeworth",zh:"\u53F2\u94CE\u514B\u6E25\u65AF"},alt:["Castle Stokeworth","\u53F2\u94CE\u514B\u6E25\u65AF\u57CE"],summary:{en:"A castle with farmland a short way north of King's Landing, seat of House Stokeworth. With Rosby, its fields helped feed the capital during the war. Lady Tanda's family spends much of its time at court.",zh:"\u541B\u4E34\u4EE5\u5317\u4E0D\u8FDC\u5904\u4E00\u5EA7\u5E26\u6709\u519C\u7530\u7684\u57CE\u5821\uFF0C\u53F2\u94CE\u514B\u6E25\u65AF\u5BB6\u65CF\u7684\u5C45\u57CE\u3002\u6218\u4E89\u671F\u95F4\uFF0C\u5B83\u4E0E\u7F57\u65AF\u6BD4\u7684\u7530\u5730\u4E00\u540C\u4E3A\u9996\u90FD\u63D0\u4F9B\u53E3\u7CAE\u3002\u5766\u59B2\u592B\u4EBA\u4E00\u5BB6\u5E38\u5E74\u6D41\u8FDE\u5BAB\u5EF7\u3002"},houses:["stokeworth"],refs:["asos","affc"],confidence:"medium",spoiler:{en:"In A Feast for Crows the sellsword Bronn becomes master of Stokeworth through his marriage to Lollys and the deaths of her mother and sister.",zh:"\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u4E2D\uFF0C\u4F63\u5175\u6CE2\u9686\u56E0\u5A36\u4E86\u7F57\u8389\u4E1D\uFF0C\u53C8\u9022\u5176\u6BCD\u4EB2\u4E0E\u59D0\u59D0\u76F8\u7EE7\u6B7B\u53BB\uFF0C\u6210\u4E86\u53F2\u94CE\u514B\u6E25\u65AF\u7684\u4E3B\u4EBA\u3002"}},{id:"rosby",kind:"castle",region:"crownlands",at:[480,908],rank:2,names:{en:"Rosby",zh:"\u7F57\u65AF\u6BD4\u57CE"},alt:["Rosby Castle"],summary:{en:"A small castle and town just north-east of King's Landing on the Rosby road, the shortest way from the capital to Duskendale. Its lord, the coughing Gyles Rosby, sits on the small council. Its granaries mattered when the capital went hungry.",zh:"\u541B\u4E34\u4E1C\u5317\u4E0D\u8FDC\u3001\u7F57\u65AF\u6BD4\u8DEF\u65C1\u7684\u5C0F\u57CE\u5821\u4E0E\u5E02\u9547\uFF1B\u7F57\u65AF\u6BD4\u8DEF\u662F\u9996\u90FD\u901A\u5F80\u66AE\u8C37\u9547\u7684\u6700\u8FD1\u8DEF\u7EBF\u3002\u57CE\u4E3B\u76D6\u5C14\u65AF\xB7\u7F57\u65AF\u6BD4\u54B3\u55FD\u4E0D\u6B62\uFF0C\u5728\u5FA1\u524D\u4F1A\u8BAE\u4EFB\u804C\u3002\u9996\u90FD\u95F9\u9965\u8352\u65F6\uFF0C\u8FD9\u91CC\u7684\u7CAE\u4ED3\u4E3E\u8DB3\u8F7B\u91CD\u3002"},houses:["rosby"],refs:["acok","affc"],confidence:"medium"},{id:"duskendale",kind:"town",region:"crownlands",at:[506,906],rank:3,names:{en:"Duskendale",zh:"\u66AE\u8C37\u9547"},alt:["Dusk","\u66AE\u8C37\u57CE"],summary:{en:"A port town on the northern shore of Blackwater Bay that takes King's Landing's overflow trade. Its lords the Darklyns once held King Aerys II prisoner here for half a year \u2014 the Defiance of Duskendale \u2014 and were destroyed for it; House Rykker now rules from the Dun Fort.",zh:"\u9ED1\u6C34\u6E7E\u5317\u5CB8\u7684\u6E2F\u53E3\u57CE\u9547\uFF0C\u5206\u62C5\u541B\u4E34\u5BB9\u7EB3\u4E0D\u4E0B\u7684\u8D38\u6613\u3002\u5176\u65E7\u9886\u4E3B\u8FBE\u514B\u6797\u5BB6\u65CF\u66FE\u5C06\u56FD\u738B\u4F0A\u91CC\u65AF\u4E8C\u4E16\u6263\u62BC\u4E8E\u6B64\u957F\u8FBE\u534A\u5E74\uFF0C\u53F2\u79F0\u201C\u66AE\u8C37\u9547\u4E4B\u53D8\u201D\uFF0C\u4E8B\u540E\u6EE1\u95E8\u88AB\u706D\uFF1B\u5982\u4ECA\u7531\u96F7\u514B\u5BB6\u65CF\u5728\u6697\u5821\u7EDF\u6CBB\u3002"},houses:["rykker","darklyn","hollard"],refs:["asos","affc","twoiaf"],confidence:"high"},{id:"dun-fort",kind:"castle",region:"crownlands",at:[511,912],rank:1,names:{en:"The Dun Fort",zh:"\u6697\u5821"},alt:["Dun Fort"],summary:{en:"The castle overlooking Duskendale's harbour. Aerys II was held captive in its dungeons during the Defiance until Ser Barristan Selmy entered the town alone and brought him out.",zh:"\u4FEF\u4E34\u66AE\u8C37\u9547\u6E2F\u53E3\u7684\u57CE\u5821\u3002\u201C\u66AE\u8C37\u9547\u4E4B\u53D8\u201D\u671F\u95F4\uFF0C\u4F0A\u91CC\u65AF\u4E8C\u4E16\u88AB\u56DA\u4E8E\u5176\u5730\u7262\uFF0C\u76F4\u5230\u5DF4\u5229\u65AF\u5766\xB7\u8D5B\u5C14\u5F25\u7235\u58EB\u53EA\u8EAB\u6F5C\u5165\uFF0C\u5C06\u4ED6\u6551\u51FA\u3002"},houses:["rykker","darklyn"],refs:["asos","affc"],confidence:"medium"},{id:"rooks-rest",kind:"castle",region:"crownlands",at:[532,906],rank:2,names:{en:"Rook's Rest",zh:"\u9E26\u6816\u5821"},alt:["Rooks Rest"],summary:{en:"Seat of House Staunton on the northern shore of Blackwater Bay, beyond Duskendale toward Crackclaw Point. It is remembered chiefly for a battle of the Dance of the Dragons fought around its walls.",zh:"\u65AF\u5766\u987F\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u9ED1\u6C34\u6E7E\u5317\u5CB8\u3001\u66AE\u8C37\u9547\u4EE5\u4E1C\u901A\u5F80\u87F9\u722A\u534A\u5C9B\u7684\u65B9\u5411\u3002\u5B83\u4E4B\u6240\u4EE5\u4E3A\u4EBA\u94ED\u8BB0\uFF0C\u4E3B\u8981\u56E0\u4E3A\u201C\u8840\u9F99\u72C2\u821E\u201D\u4E2D\u5728\u5176\u57CE\u4E0B\u7206\u53D1\u7684\u4E00\u573A\u5927\u6218\u3002"},houses:["staunton"],refs:["twoiaf"],confidence:"low"},{id:"hayford",kind:"castle",region:"crownlands",at:[444,915],rank:2,names:{en:"Hayford",zh:"\u6D77\u798F\u7279\u57CE"},alt:["Hayford Castle"],summary:{en:"A hilltop castle beside a stream, less than a day's ride from King's Landing. Jaime Lannister's host camps beneath it on the way to Riverrun; its lady is the infant Ermesande Hayford, married to the missing Tyrek Lannister.",zh:"\u5EFA\u5728\u5C0F\u5C71\u9876\u4E0A\u7684\u57CE\u5821\uFF0C\u65C1\u6709\u6EAA\u6D41\uFF0C\u8DDD\u541B\u4E34\u4E0D\u5230\u4E00\u5929\u8DEF\u7A0B\u3002\u8A79\u59C6\xB7\u5170\u5C3C\u65AF\u7279\u7387\u519B\u524D\u5F80\u5954\u6D41\u57CE\u9014\u4E2D\u66FE\u5728\u5C71\u4E0B\u624E\u8425\uFF1B\u57CE\u4E3B\u662F\u5C1A\u5728\u8941\u8913\u4E2D\u7684\u827E\u6885\u6563\u5FB7\xB7\u6D77\u798F\u7279\uFF0C\u5979\u5DF2\u4E0E\u5931\u8E2A\u7684\u6CF0\u745E\u514B\xB7\u5170\u5C3C\u65AF\u7279\u6210\u5A5A\u3002"},houses:["hayford","hogg"],refs:["affc"],confidence:"medium"},{id:"sows-horn",kind:"castle",region:"crownlands",at:[452,897],rank:1,names:{en:"Sow's Horn",zh:"\u6BCD\u732A\u89D2"},alt:["Sows Horn"],summary:{en:"A stout stone towerhouse near the riverlands border, seat of the landed knights of House Hogg, who serve the Hayfords. Lannister raiders tried to burn it during the war, but its thick walls would not catch.",zh:"\u9760\u8FD1\u6CB3\u95F4\u5730\u8FB9\u754C\u7684\u4E00\u5EA7\u575A\u56FA\u77F3\u780C\u5854\u697C\uFF0C\u970D\u683C\u5BB6\u65CF\u7684\u5C45\u6240\uFF1B\u8BE5\u5BB6\u65CF\u662F\u6709\u5C01\u5730\u7684\u9A91\u58EB\uFF0C\u4F8D\u5949\u6D77\u798F\u7279\u5BB6\u65CF\u3002\u6218\u4E89\u4E2D\u5170\u5C3C\u65AF\u7279\u7684\u52AB\u63A0\u90E8\u961F\u66FE\u8BD5\u56FE\u7EB5\u706B\u711A\u70E7\uFF0C\u4F46\u539A\u5B9E\u7684\u77F3\u5899\u70E7\u4E0D\u8D77\u6765\u3002"},houses:["hogg"],refs:["awoiaf"],confidence:"low"},{id:"the-antlers",kind:"castle",region:"crownlands",at:[474,890],rank:1,names:{en:"The Antlers",zh:"\u9E7F\u89D2\u5821"},alt:["Antlers"],summary:{en:"Seat of House Buckwell, north of King's Landing and north-west of Rosby and Duskendale. It is a modest lordship of the king's own domain, rarely visited in the novels.",zh:"\u5DF4\u514B\u5A01\u5C14\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u541B\u4E34\u4EE5\u5317\u3001\u7F57\u65AF\u6BD4\u4E0E\u66AE\u8C37\u9547\u7684\u897F\u5317\u65B9\u3002\u8FD9\u662F\u738B\u5BA4\u76F4\u8F96\u9886\u5730\u5185\u4E00\u5904\u4E0D\u5927\u7684\u9886\u4E3B\u5C01\u5730\uFF0C\u5C0F\u8BF4\u4E2D\u9C9C\u5C11\u7740\u58A8\u3002"},houses:["buckwell"],refs:["twoiaf","awoiaf"],confidence:"low"},{id:"brownhollow",kind:"castle",region:"crownlands",at:[530,884],rank:1,names:{en:"Brownhollow",zh:"\u8910\u8C37\u5821"},alt:["Brown Hollow"],summary:{en:"One of the two seats of House Brune on Crackclaw Point, a modest holdfast among the pines and bogs. Like its neighbours it guards its independence jealously.",zh:"\u5E03\u4F26\u5BB6\u65CF\u5728\u87F9\u722A\u534A\u5C9B\u7684\u4E24\u5904\u5C45\u6240\u4E4B\u4E00\uFF0C\u662F\u677E\u6797\u4E0E\u6CBC\u6CFD\u95F4\u4E00\u5EA7\u4E0D\u5927\u7684\u636E\u70B9\u3002\u4E0E\u90BB\u5C45\u4EEC\u4E00\u6837\uFF0C\u5B83\u5BF9\u81EA\u5BB6\u7684\u72EC\u7ACB\u770B\u5F97\u6781\u91CD\u3002"},houses:["brune-of-brownhollow"],refs:["twoiaf"],confidence:"low"},{id:"dyre-den",kind:"castle",region:"crownlands",at:[546,892],rank:1,names:{en:"The Dyre Den",zh:"\u51F6\u7A74\u5821"},alt:["Dyre Den"],summary:{en:"The other seat of House Brune on Crackclaw Point. Like the rest of the Crackclaw lords, the Brunes had to choose between Stannis and the Iron Throne after the Blackwater, when the crown offered pardons.",zh:"\u5E03\u4F26\u5BB6\u65CF\u5728\u87F9\u722A\u534A\u5C9B\u7684\u53E6\u4E00\u5904\u5C45\u57CE\u3002\u9ED1\u6C34\u6CB3\u4E4B\u5F79\u540E\u738B\u5BA4\u63D0\u51FA\u8D66\u514D\uFF0C\u5E03\u4F26\u5BB6\u65CF\u4E0E\u87F9\u722A\u534A\u5C9B\u5176\u4ED6\u9886\u4E3B\u4E00\u6837\uFF0C\u4E0D\u5F97\u4E0D\u5728\u53F2\u5766\u5C3C\u65AF\u4E0E\u94C1\u738B\u5EA7\u4E4B\u95F4\u4F5C\u51FA\u6289\u62E9\u3002"},houses:["brune-of-the-dyre-den"],refs:["affc","twoiaf","awoiaf"],confidence:"low"},{id:"the-whispers",kind:"ruin",region:"crownlands",at:[554,875],rank:2,names:{en:"The Whispers",zh:"\u4F4E\u8BED\u5821"},alt:["Whispers"],summary:{en:"A ruined castle on the cliffs of Crackclaw Point, once held by House Crabb and linked in local legend to the giant Ser Clarence Crabb. Smugglers use its cove, and in A Feast for Crows Brienne's search leads her there with the guide Nimble Dick.",zh:"\u87F9\u722A\u534A\u5C9B\u6D77\u5D16\u4E0A\u7684\u4E00\u5EA7\u57CE\u5821\u5E9F\u589F\uFF0C\u6614\u65E5\u5F52\u514B\u83B1\u52C3\u5BB6\u65CF\u6240\u6709\uFF0C\u5F53\u5730\u4F20\u8BF4\u5C06\u5B83\u4E0E\u5DE8\u4EBA\u822C\u7684\u514B\u62C9\u4F26\u65AF\xB7\u514B\u83B1\u52C3\u7235\u58EB\u8054\u7CFB\u5728\u4E00\u8D77\u3002\u8D70\u79C1\u8005\u5229\u7528\u5176\u4E0B\u7684\u6D77\u6E7E\uFF1B\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u4E2D\uFF0C\u5E03\u857E\u59AE\u5728\u5411\u5BFC\u201C\u7075\u5DE7\u7684\u8FEA\u514B\u201D\u5E26\u9886\u4E0B\u5BFB\u8BBF\u81F3\u6B64\u3002"},houses:["crabb"],refs:["affc"],confidence:"medium",spoiler:{en:"At the Whispers Brienne runs into survivors of the Brave Companions; Nimble Dick is killed and Brienne kills the outlaws in the fight.",zh:"\u5E03\u857E\u59AE\u5728\u4F4E\u8BED\u5821\u649E\u4E0A\u52C7\u58EB\u56E2\u7684\u6B8B\u4F59\u532A\u5F92\uFF1B\u7075\u5DE7\u7684\u8FEA\u514B\u9047\u5BB3\uFF0C\u5E03\u857E\u59AE\u5728\u640F\u6597\u4E2D\u5C06\u8FD9\u4E9B\u4EA1\u547D\u5F92\u5C3D\u6570\u6740\u6B7B\u3002"}},{id:"battle-of-the-blackwater",kind:"battle",region:"crownlands",at:[485,935],rank:2,names:{en:"Battle of the Blackwater",zh:"\u9ED1\u6C34\u6CB3\u4E4B\u5F79"},alt:["Blackwater battle","\u9ED1\u6C34\u6CB3\u4E4B\u6218"],summary:{en:"Stannis Baratheon's assault on King's Landing in A Clash of Kings. His fleet was trapped by a chain across the river mouth and set ablaze with wildfire, and his army on the south bank broke when Tywin Lannister and the Tyrells fell on its flank.",zh:"\u300A\u5217\u738B\u7684\u7EB7\u4E89\u300B\u4E2D\u53F2\u5766\u5C3C\u65AF\xB7\u62DC\u62C9\u5E2D\u6069\u5BF9\u541B\u4E34\u7684\u8FDB\u653B\u3002\u4ED6\u7684\u8230\u961F\u88AB\u6A2A\u8DE8\u6CB3\u53E3\u7684\u94C1\u94FE\u56F0\u4F4F\uFF0C\u906D\u91CE\u706B\u711A\u6BC1\uFF1B\u5357\u5CB8\u5927\u519B\u53C8\u88AB\u6CF0\u6E29\xB7\u5170\u5C3C\u65AF\u7279\u4E0E\u63D0\u5229\u5C14\u5BB6\u65CF\u7684\u63F4\u519B\u4ECE\u4FA7\u7FFC\u51FB\u6E83\u3002"},houses:[],refs:["acok"],confidence:"high"},{id:"battle-of-the-gullet",kind:"battle",region:"crownlands",at:[574,959],rank:1,names:{en:"Battle of the Gullet",zh:"\u54BD\u5589\u6D77\u5CE1\u4E4B\u6218"},alt:["Gullet battle"],summary:{en:"One of the bloodiest sea battles in Westerosi history, fought during the Dance of the Dragons when the Triarchy's fleet tried to force the Gullet. Velaryon ships, dragons and burning galleys filled the strait.",zh:"\u7EF4\u65AF\u7279\u6D1B\u5386\u53F2\u4E0A\u6700\u60E8\u70C8\u7684\u6D77\u6218\u4E4B\u4E00\uFF0C\u53D1\u751F\u4E8E\u201C\u8840\u9F99\u72C2\u821E\u201D\u671F\u95F4\uFF0C\u4E09\u57CE\u8054\u76DF\u7684\u8230\u961F\u4F01\u56FE\u5F3A\u95EF\u54BD\u5589\u6D77\u5CE1\u3002\u74E6\u5217\u5229\u5B89\u6218\u8239\u3001\u5DE8\u9F99\u4E0E\u71C3\u70E7\u7684\u6868\u5E06\u8239\u6324\u6EE1\u4E86\u6574\u6761\u6D77\u5CE1\u3002"},houses:["velaryon","targaryen"],refs:["twoiaf"],confidence:"medium"},{id:"battle-of-rooks-rest",kind:"battle",region:"crownlands",at:[537,900],rank:1,names:{en:"Battle of Rook's Rest",zh:"\u9E26\u6816\u5821\u4E4B\u6218"},alt:["Rooks Rest battle"],summary:{en:"An ambush of the Dance of the Dragons: when Princess Rhaenys flew her dragon Meleys to relieve Rook's Rest, she was set upon by Aegon II and Prince Aemond on their dragons, and she and Meleys were killed.",zh:"\u201C\u8840\u9F99\u72C2\u821E\u201D\u4E2D\u7684\u4E00\u573A\u4F0F\u51FB\uFF1A\u96F7\u59AE\u4E1D\u516C\u4E3B\u9A91\u7740\u5DE8\u9F99\u7C73\u52D2\u65AF\u524D\u6765\u4E3A\u9E26\u6816\u5821\u89E3\u56F4\uFF0C\u906D\u4F0A\u803F\u4E8C\u4E16\u4E0E\u4F0A\u8499\u5FB7\u738B\u5B50\u9A7E\u9F99\u56F4\u653B\uFF0C\u5979\u4E0E\u7C73\u52D2\u65AF\u53CC\u53CC\u6B92\u547D\u3002"},houses:["staunton","targaryen"],refs:["twoiaf"],confidence:"medium"}]};export{e as default};
